package com.ferreteriahuaman.service;
import com.ferreteriahuaman.repository.*;import com.ferreteriahuaman.security.AuthFailure;import com.ferreteriahuaman.security.AuthModels.Identity;import com.fasterxml.jackson.databind.ObjectMapper;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.mockito.Mockito.*;import static org.assertj.core.api.Assertions.*;
class QuoteServiceTest {QuoteRepository repo=mock(QuoteRepository.class);QuoteService service=new QuoteService(repo,mock(BusinessTransactions.class),mock(CashRepository.class),mock(AuthStore.class),new ObjectMapper());Identity actor=new Identity(1,"usuario","Nombre","Apellido","VEN",false,Set.of("COC.COTIZAR"),UUID.randomUUID(),OffsetDateTime.now().plusMinutes(30));
 @Test void rejectsInvalidFiltersBeforeQuery(){assertThatThrownBy(()->service.list(actor,"","OTRO",null,null,0,20)).isInstanceOf(AuthFailure.class);assertThatThrownBy(()->service.list(actor,"","",LocalDate.of(2026,2,1),LocalDate.of(2026,1,1),0,20)).isInstanceOf(AuthFailure.class);assertThatThrownBy(()->service.list(actor,"","",null,null,-1,20)).isInstanceOf(AuthFailure.class);verifyNoInteractions(repo);}
 @Test void sellerCannotReadAnotherSellerQuote(){when(repo.get(2,false)).thenReturn(Optional.of(Map.of("vendedorId",2L)));assertThatThrownBy(()->service.details(actor,2)).isInstanceOf(AuthFailure.class);verify(repo,never()).lines(anyLong());}
}
